ALTER TABLE inventory_items ADD COLUMN equipment_slot TEXT GENERATED ALWAYS AS (CASE
 WHEN definition_id IN ('original/iw1','original/iw2','original/iw3','original/iw4','original/iw5','original/iw6','original/iw7','original/iw8','original/iw9','original/iw10','original/iw11','original/iw12','original/iw13','original/iw14','original/iw15','original/iw16','original/iw17','original/iw18','original/iw19','original/iw20','original/iw21','original/iw22','original/iw23','original/iw24','original/iw25','original/iw26','original/iw27','original/iw28','original/iw29','original/iw30','original/iw31','original/iw32','original/iw33','original/iw34','original/iw35','original/iw36','original/iw37','original/iw38','original/iw39','original/iw40','original/iw41','original/iw42','original/iw43','original/iw44','original/iw45','original/iw46','original/iw47','original/iw48','original/iw49','original/iw50','original/iw51','original/iw52','original/iw53','original/iw54','original/iw55','original/iw56','sword','weapon_2','weapon_3') THEN 'weapon'
 WHEN definition_id IN ('original/if9','original/if19','original/if27','original/if38','original/if47','original/if56','original/if65','original/if74','original/if83') THEN 'pendant'
 WHEN definition_id IN ('original/if2','original/if11','original/if21','original/if30','original/if43','original/if49','original/if61','original/if67','original/if76','armor_2','armor_3') THEN 'armor'
 WHEN definition_id IN ('original/if3','original/if12','original/if22','original/if31','original/if41','original/if50','original/if59','original/if68','original/if77') THEN 'wrist'
 WHEN definition_id IN ('original/if4','original/if13','original/if23','original/if32','original/if42','original/if51','original/if60','original/if69','original/if78') THEN 'belt'
 WHEN definition_id IN ('original/if5','original/if14','original/if24','original/if33','original/if40','original/if52','original/if58','original/if70','original/if79') THEN 'pants'
 WHEN definition_id IN ('original/if6','original/if16','original/if25','original/if34','original/if44','original/if53','original/if62','original/if71','original/if80') THEN 'boots'
 WHEN definition_id IN ('original/if7','original/if17','original/if28','original/if36','original/if45','original/if54','original/if63','original/if72','original/if81') THEN 'ring'
 WHEN definition_id IN ('original/if8','original/if18','original/if26','original/if37','original/if46','original/if55','original/if64','original/if73','original/if82') THEN 'necklace'
 WHEN definition_id IN ('original/if1','original/if10','original/if20','original/if29','original/if39','original/if48','original/if57','original/if66','original/if75') THEN 'hat'
 ELSE NULL END) STORED;
ALTER TABLE inventory_items ADD CONSTRAINT inventory_items_check CHECK(NOT equipped OR (equipment_slot IS NOT NULL AND quantity=1));
ALTER TABLE inventory_items ADD CONSTRAINT equipment_quantity_one CHECK(equipment_slot IS NULL OR quantity=1);
CREATE UNIQUE INDEX one_equipped_per_slot ON inventory_items(character_id,equipment_slot) WHERE equipped;
